PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE IF NOT EXISTS "analytics_statisticaldata" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "data_type" varchar(50) NOT NULL UNIQUE, "title" varchar(200) NOT NULL, "description" text NOT NULL, "table_html" text NOT NULL, "raw_data" text NULL CHECK ((JSON_VALID("raw_data") OR "raw_data" IS NULL)), "is_active" bool NOT NULL, "created_at" datetime NOT NULL, "updated_at" datetime NOT NULL, "chart_image" varchar(100) NULL);
COMMIT;
